using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using MiniStore.Domain.Entities;
namespace MiniStore.Infrastructure.Persistence.Configurations;
public sealed class LandedCostConfiguration:IEntityTypeConfiguration<LandedCost>,IEntityTypeConfiguration<LandedCostComponent>,IEntityTypeConfiguration<LandedCostAllocation>
{
 public void Configure(EntityTypeBuilder<LandedCost>b){b.HasKey(x=>x.Id);b.Property(x=>x.CostNumber).HasMaxLength(50).IsRequired();b.Property(x=>x.ExternalReference).HasMaxLength(100).IsRequired();b.Property(x=>x.NormalizedExternalReference).HasMaxLength(100).IsRequired();b.Property(x=>x.Notes).HasMaxLength(1000);b.Property(x=>x.CreatedByUserId).HasMaxLength(450).IsRequired();b.Ignore(x=>x.TotalAmount);b.Ignore(x=>x.CapitalizedAmount);b.Ignore(x=>x.ExpensedAmount);b.HasIndex(x=>x.CostNumber).IsUnique();b.HasIndex(x=>x.NormalizedExternalReference).IsUnique();b.HasOne<GoodsReceipt>().WithMany().HasForeignKey(x=>x.GoodsReceiptId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Warehouse>().WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Components).WithOne().HasForeignKey(x=>x.LandedCostId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.Allocations).WithOne().HasForeignKey(x=>x.LandedCostId).OnDelete(DeleteBehavior.Cascade);}
 public void Configure(EntityTypeBuilder<LandedCostComponent>b){b.HasKey(x=>x.Id);b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.Description).HasMaxLength(250);b.HasIndex(x=>new{x.LandedCostId,x.Type}).IsUnique();}
 public void Configure(EntityTypeBuilder<LandedCostAllocation>b){b.HasKey(x=>x.Id);b.Property(x=>x.AllocationBasis).HasPrecision(24,8);b.Property(x=>x.AllocatedAmount).HasPrecision(18,2);b.Property(x=>x.CapitalizedAmount).HasPrecision(18,2);b.Property(x=>x.ExpensedAmount).HasPrecision(18,2);b.Property(x=>x.AverageUnitCostBefore).HasPrecision(24,8);b.Property(x=>x.AverageUnitCostAfter).HasPrecision(24,8);b.Property(x=>x.ProductCodeSnapshot).HasMaxLength(100).IsRequired();b.Property(x=>x.ProductNameSnapshot).HasMaxLength(250).IsRequired();b.HasIndex(x=>new{x.LandedCostId,x.GoodsReceiptLineId}).IsUnique();b.HasOne<GoodsReceiptLine>().WithMany().HasForeignKey(x=>x.GoodsReceiptLineId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);}
}
